using System;using System.Linq;using BeamScheduleFormatter;
class AngleSegmentsTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,string why){Check(Math.Abs(a-b)<1e-7,why);}
 static void Main(){var member=new SteelCutDemand{Member="TC",Specification="L75x75x5 | A36",Length=10.322,Quantity=2,KgM=5.7};var parts=AngleSegments.Expand(member);Check(parts.Count==2&&member.Parts==2,"10.322m is allocated as two stock portions per item");Near(parts[0].Length,6,"First stock portion");Near(parts[1].Length,4.322,"Remainder");Near(parts.Sum(s=>s.Length),10.322,"No splice/lap length is added");Near(AngleQuantityBasis.RequiredPieces(10.322,1),1.7203333333333333,"Single item is 1.72 required equivalent pcs when displayed");Near(AngleQuantityBasis.RequiredPieces(10.322,2),3.4406666666666665,"Required equivalent includes quantity exactly once");Check(parts.All(s=>s.Quantity==2&&s.Source==member),"Source quantities retained");var stocks=SteelCutPlanner.Allocate(parts);Check(stocks.Count==4,"Four whole stocks for two long items before offcut reuse");Near(stocks.Sum(s=>s.Remaining),3.356,"Final reusable leftovers");Near(SteelCutPlanner.PurchaseKg(stocks,member),24*5.7,"Whole purchase allocation reconciles");var other=new SteelCutDemand{Member="Other row",Specification=member.Specification,Length=1.5,Quantity=2,KgM=5.7};stocks=SteelCutPlanner.Allocate(parts.Concat(new[]{other}));Check(stocks.Count==4,"Other compatible rows reuse leftovers without another stock");Near(stocks.Sum(s=>s.Remaining),.356,"Only final unused offcuts are counted as remaining");Near(SteelCutPlanner.PurchaseKg(stocks,member)+SteelCutPlanner.PurchaseKg(stocks,other),24*5.7,"Shared row allocations reconcile to total stock weight");other.Specification+=" different grade";Check(SteelCutPlanner.Allocate(parts.Concat(new[]{other})).Count==5,"Different grade cannot reuse stock");var profile=new SteelProfile{Kind="Angle bar",H=75,B=75,T=5};Near(AngleQuantityBasis.PaintingArea(profile,10.322,1),3.0966,"Painting uses installed length and angle perimeter, excluding purchased waste");var exact=AngleSegments.Expand(new SteelCutDemand{Member="Exact",Specification=member.Specification,Length=18,Quantity=1,KgM=5.7});Check(exact.Count==3&&exact.All(s=>s.Length==6),"Exact stock multiple adds no connection lengths");Console.WriteLine("PASS: "+checks+" fractional required pcs, whole-stock purchase, reuse and installed painting basis checks");}
}
